                  {[
                    {
                      step: "1",
                      title: "Add zip codes",
                      desc: "Enter the zip codes you deliver to, or import them via CSV.",
                      action: "Add zip codes",
                      href: "/app/zip-codes",
                      primary: true,
                    },
                    {
                      step: "2",
                      title: "Customize the widget",
                      desc: "Set colors, text, and position to match your store.",
                      action: "Customize",
                      href: "/app/widget",
                      primary: false,
                    },
                    {
                      step: "3",
                      title: "Add delivery rules",
                      desc: "Set delivery fees, cutoff times, and schedules per zone.",
                      action: "Add rules",
                      href: "/app/delivery-rules",
                      primary: false,
                    },
                  ].map((item) => (
                    <Box
                      key={item.step}
                      padding="400"
                      background="bg-surface-secondary"
                      borderRadius="300"
                    >
                      <BlockStack gap="200">
                        <InlineStack gap="200" blockAlign="center">
                          <Box
                            background="bg-fill-brand"
                            borderRadius="full"
                            padding="100"
                            minWidth="24px"
                            minHeight="24px"
                          >
                            <Text
                              as="span"
                              variant="bodySm"
                              fontWeight="bold"
                              alignment="center"
                              tone="text-inverse"
                            >
                              {item.step}
                            </Text>
                          </Box>
                          <Text as="h3" variant="headingSm">
                            {item.title}
                          </Text>
                        </InlineStack>
                        <Text as="p" variant="bodySm" tone="subdued">
                          {item.desc}
                        </Text>
                        <Button
                          variant={item.primary ? "primary" : undefined}
                          size="slim"
                          onClick={() => navigate(item.href)}
                        >
                          {item.action}
                        </Button>
                      </BlockStack>
                    </Box>
                  ))}
                </InlineGrid>
              </BlockStack>
            </Card>
          )}

          {/* ─── 5. NAVIGATION ─── */}
          <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
            {[
              {
                title: "Zip Codes",
                desc: "Add, edit, import, or export your service areas.",
                stat: stats.total > 0 ? `${stats.total} total` : undefined,
                action: "Manage zip codes",
                href: "/app/zip-codes",
              },
              {
                title: "Delivery Rules",
                desc: "Set fees, cutoff times, and schedules by zone.",
