          }
        }

        /* eslint-enable @typescript-eslint/no-explicit-any */
      }
    }
  } catch {
    // Theme detection failed — leave appEmbedEnabled as false
  }

  return {
    stats,
    subscription,
    appEmbedEnabled,
    activeThemeName,
    themeEditorUrl,
    themeEditorAppEmbedsUrl,
  };
};

