// ---------------------------------------------------------------------------

export async function sendZipAvailableNotification(
  to: string,
  zipCode: string,
  shop: string,
  shopUrl: string,
): Promise<boolean> {
  const pm = getClient();
  if (!pm) return false;

  const name = shopDisplayName(shop);

  try {
    await pm.sendEmail({
      From: getFromEmail(),
      To: to,
      Subject: `Great news! We now deliver to ${zipCode}`,
      HtmlBody: `
